INSERT INTO `v1_79d80e3c63acba179e1e3d2b3db73a9f28cab9d9a201101aa52e6526506fac36` VALUES (1, 2, "イベントボスには非常に高い「Total HP」が設定されております。\n「Total HP」は、皆さまがバトル中に与えたダメージの分だけ減らせる\nのだとか。豪華報酬を目指し、力を合わせて討伐いたしましょう。", 1, 1012);
INSERT INTO `v1_79d80e3c63acba179e1e3d2b3db73a9f28cab9d9a201101aa52e6526506fac36` VALUES (1, 3, "ボスバトルは、イベント期間中に配布される「討伐チケット」を消費して\n挑戦できます。また、難易度は「ボス詳細」から変更できますよ。\n討伐を達成した難易度はスキップも行えるので、活用してくださいまし。", 1, 1013);
INSERT INTO `v1_79d80e3c63acba179e1e3d2b3db73a9f28cab9d9a201101aa52e6526506fac36` VALUES (1, 4, "報酬交換では「討伐報酬券」と様々なアイテムを交換できます。\n目玉となるリセット対象報酬を引くことで、より多くのアイテムが\n獲得できる次のラインナップへと進めるそうです。", 2, 1021);
